package zw.co.hyperfeeds.content;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/content")public class ContentController{private final JdbcClient jdbc;public ContentController(JdbcClient j){jdbc=j;}@GetMapping("/announcements")List<Map<String,Object>>announcements(@RequestParam(required=false)UUID branchId){return jdbc.sql("select id,title,body,branch_id,published_from,published_until from announcements where active and published_from<=now() and (published_until is null or published_until>now()) and (branch_id is null or branch_id=:b) order by published_from desc").param("b",branchId).query().listOfRows();}@GetMapping("/specials")List<Map<String,Object>>specials(@RequestParam(required=false)UUID branchId){return jdbc.sql("select s.id,s.product_id,p.name,s.branch_id,s.promotional_price,s.currency,s.starts_at,s.ends_at from specials s join products p on p.id=s.product_id where s.active and s.starts_at<=now() and s.ends_at>now() and (s.branch_id is null or s.branch_id=:b) order by s.ends_at").param("b",branchId).query().listOfRows();}@PostMapping("/announcements")@PreAuthorize("hasRole('ADMIN')")@ResponseStatus(HttpStatus.CREATED)UUID announcement(@Valid@RequestBody Announcement r){UUID id=UUID.randomUUID();jdbc.sql("insert into announcements(id,title,body,branch_id,published_from,published_until) values(:id,:t,:body,:b,:from,:until)").param("id",id).param("t",r.title).param("body",r.body).param("b",r.branchId).param("from",r.publishedFrom).param("until",r.publishedUntil).update();return id;}@PostMapping("/specials")@PreAuthorize("hasRole('ADMIN')")@ResponseStatus(HttpStatus.CREATED)UUID special(@Valid@RequestBody Special r){UUID id=UUID.randomUUID();jdbc.sql("insert into specials(id,product_id,branch_id,promotional_price,currency,starts_at,ends_at) values(:id,:p,:b,:price,:c,:start,:end)").param("id",id).param("p",r.productId).param("b",r.branchId).param("price",r.promotionalPrice).param("c",r.currency.toUpperCase()).param("start",r.startsAt).param("end",r.endsAt).update();return id;}record Announcement(@NotBlank String title,@NotBlank String body,UUID branchId,@NotNull Instant publishedFrom,Instant publishedUntil){}record Special(@NotNull UUID productId,UUID branchId,@DecimalMin("0")BigDecimal promotionalPrice,@Pattern(regexp="[A-Za-z]{3}")String currency,@NotNull Instant startsAt,@NotNull Instant endsAt){} }
